"""
xml parser
"""
import re
from builtins import object
from lxml import etree
from .datetime_operations import DatetimeOperations


class XmlParser(object):
    """
    xml parser
    """
    def __init__(self):
        self.datetime_ops = DatetimeOperations()

    def parse_and_return_dict(self, pm_file):
        """
        Function to parse and return dict
        """
        all_intervals_data = {}
        root_element = etree.parse(pm_file)
        for pmsetup_element in root_element.getiterator('PMSetup'):
            unique_key = self._build_unique_starttime_key(pmsetup_element)
            all_intervals_data[unique_key] = self._get_all_mocs_data_in_interval_as_dict(
                pmsetup_element)
        return all_intervals_data

    def _build_unique_starttime_key(self, pmsetup_element):
        start_time = self.datetime_ops.format_time_stamp_from_xml_or_json(
            pmsetup_element.attrib['startTime'])
        interval_type = self._get_interval_type(pmsetup_element)
        return start_time + '-' + interval_type  # Add interval_type when required

    def _get_interval_type(self, pmsetup_element):
        return pmsetup_element.attrib['interval']

    def _get_all_mocs_data_in_interval_as_dict(self, pmsetup_element):
        interval_data = {}
        for pmmoresult_element in pmsetup_element.getiterator('PMMOResult'):
            moc_unique_id, pm_counters_dict = self._get_moc_unique_id_and_its_counters(
                pmmoresult_element)
            interval_data[moc_unique_id] = self._append_to_existing_counters(
                interval_data, moc_unique_id, pm_counters_dict)
        return interval_data

    def _get_moc_unique_id_and_its_counters(self, pmmoresult_element):
        pm_counters_dict = {}
        moc_unique_id = ''
        for child in pmmoresult_element.iter():
            if child.tag == 'DN':
                parent = child.getparent()
                if parent.attrib['dimension'] == 'network_element':
                    moc_unique_id = child.text
                elif parent.attrib['dimension'] == 'MCCMNC':
                    pm_counters_dict['mccmnc'] = child.text
            elif re.search(r'M\d+C\d+', child.tag):
                pm_counters_dict[child.tag] = child.text
                # Get Measurement type when needed . attribute name measurementType
        if moc_unique_id != '':
            return moc_unique_id, pm_counters_dict

    def _append_to_existing_counters(self, interval_data, moc_unique_id, pm_counters_dict):
        if moc_unique_id in list(interval_data.keys()):
            existing_counters = interval_data[moc_unique_id]
            existing_counters.update(pm_counters_dict)
            return existing_counters
        return pm_counters_dict
